import{_ as d,o as e,c as o,a6 as a}from"./chunks/framework.BoFLe3f3.js";const u=JSON.parse('{"title":"版本能力矩阵：15.x → 16.4","description":"把 Next.js 15.x 与 16.4 的关键行为差异整理成可验证的矩阵：每行都给出迁移动作与验证方式，避免凭印象升级。","frontmatter":{"title":"版本能力矩阵：15.x → 16.4","description":"把 Next.js 15.x 与 16.4 的关键行为差异整理成可验证的矩阵：每行都给出迁移动作与验证方式，避免凭印象升级。"},"headers":[],"relativePath":"version-matrix.md","filePath":"version-matrix.md","lastUpdated":1793422332000}'),c={name:"version-matrix.md"};function r(n,t,i,s,h,l){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="版本能力矩阵" tabindex="-1">版本能力矩阵 <a class="header-anchor" href="#版本能力矩阵" aria-label="Permalink to &quot;版本能力矩阵&quot;">​</a></h1><p>单版本教程最容易出现的误区，是「我记得 15 不是这样的」。这一页把关键差异压成一张可核对的表：<strong>变化点、迁移动作、怎么验证</strong>。</p><table tabindex="0"><thead><tr><th>能力</th><th>15.x 行为</th><th>16.4 行为</th><th>迁移动作</th><th>验证方式</th></tr></thead><tbody><tr><td>打包器</td><td>Webpack 为主，Turbopack 可选</td><td>Turbopack 默认，持久化磁盘缓存</td><td>移除自定义 Webpack 配置，改用 Turbopack 等价配置</td><td><code>next build</code> 日志确认打包器；对比构建耗时</td></tr><tr><td>请求拦截</td><td><code>middleware.ts</code>（Edge 为主）</td><td><code>proxy.ts</code>（Node 运行时）</td><td>重命名文件与导出函数，检查 matcher</td><td>访问受保护路径，确认拦截仍生效</td></tr><tr><td>动态参数</td><td><code>params</code> / <code>searchParams</code> 同步</td><td>异步，需要 <code>await</code></td><td>所有页面与布局改为 <code>await params</code></td><td>类型检查 + 直接访问动态路由</td></tr><tr><td>部分预渲染</td><td><code>experimental.ppr</code> 开关</td><td><code>cacheComponents</code> 模型</td><td>移除实验开关，按 Cache Components 拆分外壳与动态区</td><td>构建输出是否产出静态 shell</td></tr><tr><td>缓存默认值</td><td>动态为主，显式 opt-in</td><td>动态默认 + <code>use cache</code> 显式缓存</td><td>审计所有取数函数，补 <code>cacheTag</code> 与失效点</td><td>写入后读取是否立即更新</td></tr><tr><td>Edge Runtime</td><td>支持</td><td>废弃，回归 Node 运行时</td><td>移除 <code>export const runtime = &quot;edge&quot;</code></td><td>构建无相关警告；检查依赖的 Node API</td></tr><tr><td>SSR 实现</td><td>Web Streams</td><td>Node.js 原生流</td><td>通常无需改代码，检查自定义流适配</td><td>压测下 TTFB 与吞吐</td></tr><tr><td>即时导航</td><td>预取 + loading</td><td>Cache Components + Partial Prefetching + <code>instant()</code> 断言</td><td>拆分外壳，补 Playwright <code>instant()</code></td><td>点击后 100ms 内是否出现外壳</td></tr><tr><td>React Compiler</td><td>需手动开启</td><td>实验性 Rust 实现可选</td><td>在基线稳定后灰度开启</td><td>同一性能预算前后对比</td></tr><tr><td>类型检查</td><td>tsc</td><td>可选 TypeScript 7 原生移植</td><td>在 CI 增加开关与耗时对比</td><td>类型错误是否一致、耗时是否下降</td></tr><tr><td>AI 开发链路</td><td>无统一入口</td><td><code>AGENTS.md</code> + first-party Skills + Actionable Errors</td><td>接入 <code>AGENTS.md</code>，统一错误修复提示</td><td>新成员按文档能否独立启动</td></tr></tbody></table><h2 id="_16-3-→-16-4-小版本-大信号" tabindex="-1">16.3 → 16.4：小版本，大信号 <a class="header-anchor" href="#_16-3-→-16-4-小版本-大信号" aria-label="Permalink to &quot;16.3 → 16.4：小版本，大信号&quot;">​</a></h2><p>16.4 没有破坏性变更，但改变了官方推荐路径：<strong>Cache Components 从「可选尝鲜」变成「每个应用的最佳选择」</strong>。</p><table tabindex="0"><thead><tr><th>能力</th><th>16.3 行为</th><th>16.4 行为</th><th>迁移动作</th><th>验证方式</th></tr></thead><tbody><tr><td>Cache Components 定位</td><td>可选启用，官方不推荐全量使用</td><td>官方推荐所有应用开启；<code>create-next-app</code> 新项目默认开启，17 将成为默认</td><td>存量项目用官方 Skills / <code>next upgrade --agent</code> 辅助迁移</td><td>新项目 <code>next.config</code> 默认含 <code>cacheComponents: true</code></td></tr><tr><td>静态保证</td><td>无强制手段，动态组件可悄然混入</td><td><code>export const ensureStatic</code>（<code>shell</code> / <code>prefetch</code> / <code>navigation</code>），混入动态内容即构建失败</td><td>在营销页、博客等路由/布局上声明 <code>ensureStatic</code></td><td>故意加入动态组件，构建应报错</td></tr><tr><td>预取成本控制</td><td>预取要么全开要么全关</td><td><code>await navigation()</code> 把缓存内容推迟到真实导航；<code>await prefetch()</code> 把内容排除在外壳之外</td><td>把昂贵的列表/线程数据包进调用 <code>navigation()</code> 的组件</td><td>预取响应中不再包含被推迟的内容</td></tr><tr><td>升级方式</td><td>手动对照迁移指南</td><td><code>npx next@canary upgrade --agent</code> 端到端升级；<code>experimental.agentUpgrade</code> 自动提醒</td><td>配置 <code>agentUpgrade: &#39;security&#39; | &#39;latest&#39;</code></td><td>dev/build 终端出现升级提醒</td></tr><tr><td>资源占用</td><td>16.3 已大幅降内存</td><td>dev 磁盘缓存更小、服务端 HMR 惰性化、Turbopack 共享运行时让生产包更小</td><td>无需动作，升级即得</td><td>对比 <code>.next</code> 体积与 bundle 分析</td></tr><tr><td>React</td><td>19.3.0</td><td>19.3.1（随包）</td><td>升级 <code>react</code> / <code>react-dom</code></td><td><code>package.json</code> 与运行时行为一致</td></tr></tbody></table><h2 id="升级前的三个检查" tabindex="-1">升级前的三个检查 <a class="header-anchor" href="#升级前的三个检查" aria-label="Permalink to &quot;升级前的三个检查&quot;">​</a></h2><ol><li><strong>先跑内容门禁与构建</strong>：<code>pnpm check:content &amp;&amp; pnpm docs:build</code>，确认现有内容没有依赖旧行为。</li><li><strong>列出所有隐式缓存假设</strong>：搜索 <code>&quot;use cache&quot;</code>、<code>fetch(</code>、<code>cookies()</code>、<code>headers()</code>，逐个确认缓存键与失效点。</li><li><strong>准备回滚</strong>：保留上一版本产物与部署配置，记录回滚耗时；升级不是一次性动作。</li></ol><h2 id="常见误判" tabindex="-1">常见误判 <a class="header-anchor" href="#常见误判" aria-label="Permalink to &quot;常见误判&quot;">​</a></h2><ul><li>「16 默认全静态」——错。默认是动态，静态与缓存都需要显式声明。</li><li>「proxy.ts 只是改名」——错。运行时与执行边界都变了，鉴权不能只靠它。</li><li>「开了 Turbopack 就不用管构建配置」——错。自定义 loader/plugin 仍需要等价迁移。</li></ul><p>对应章节：<a href="/nextjs-tutorial-site/chapters/01-introduction/basics">第 1 章 · 基础</a>、<a href="/nextjs-tutorial-site/chapters/05-caching/advanced">第 5 章 · 缓存</a>、<a href="/nextjs-tutorial-site/chapters/09-route-handlers/advanced">第 9 章 · proxy.ts</a>、<a href="/nextjs-tutorial-site/chapters/13-testing-deployment/practice">第 13 章 · 部署</a>。</p>',11)])])}const m=d(c,[["render",r]]);export{u as __pageData,m as default};
